'use strict';

const fs = require('fs');
const path = require('path');
const Sequelize = require('sequelize');

const sequelize = new Sequelize({
  dialect: 'sqlite',
  storage: path.join(__dirname, '..', 'database.sqlite'),
  logging: false,
});

const db = { sequelize, Sequelize };

fs
  .readdirSync(__dirname)
  .filter((file) => {
    return (
      file.indexOf('.') !== 0 &&
      file !== 'index.js' &&
      file.slice(-3) === '.js'
    );
  })
  .forEach((file) => {
    const model = require(path.join(__dirname, file))(sequelize, Sequelize.DataTypes);
    db[model.name] = model;
  });

Object.keys(db).forEach((modelName) => {
  if (db[modelName].associate) {
    db[modelName].associate(db);
  }
});

module.exports = db;

'use strict';

module.exports = (sequelize, DataTypes) => {
  const User = sequelize.define(
    'User',
    {
      name: {
        type: DataTypes.STRING,
        allowNull: false,
      },
    },
    {}
  );

  User.associate = (models) => {
    User.hasMany(models.Image, {
      foreignKey: 'imageableId',
      constraints: false,
      scope: { imageableType: 'user' },
      as: 'profilePictures',
    });
  };

  return User;
};

'use strict';

module.exports = (sequelize, DataTypes) => {
  const Product = sequelize.define(
    'Product',
    {
      title: {
        type: DataTypes.STRING,
        allowNull: false,
      },
    },
    {}
  );

  Product.associate = (models) => {
    Product.hasMany(models.Image, {
      foreignKey: 'imageableId',
      constraints: false,
      scope: { imageableType: 'product' },
      as: 'productPhotos',
    });
  };

  return Product;
};

'use strict';

module.exports = (sequelize, DataTypes) => {
  const Image = sequelize.define(
    'Image',
    {
      url: {
        type: DataTypes.STRING,
        allowNull: false,
      },
      imageableId: {
        type: DataTypes.INTEGER,
        allowNull: false,
      },
      imageableType: {
        type: DataTypes.STRING,
        allowNull: false,
      },
    },
    {}
  );

  Image.associate = (models) => {
    Image.belongsTo(models.User, {
      foreignKey: 'imageableId',
      constraints: false,
      as: 'imageableUser',
    });
    Image.belongsTo(models.Product, {
      foreignKey: 'imageableId',
      constraints: false,
      as: 'imageableProduct',
    });
  };

  return Image;
};

'use strict';

const express = require('express');
const { sequelize, User, Product, Image } = require('./models');

const app = express();
app.use(express.json());

const PORT = 3000;

// POST /users
app.post('/users', async (req, res) => {
  try {
    const { name } = req.body;
    const user = await User.create({ name });
    res.status(201).json(user.toJSON());
  } catch (err) {
    res.status(400).json({ error: err.message });
  }
});

// POST /products
app.post('/products', async (req, res) => {
  try {
    const { title } = req.body;
    const product = await Product.create({ title });
    res.status(201).json(product.toJSON());
  } catch (err) {
    res.status(400).json({ error: err.message });
  }
});

// POST /images
app.post('/images', async (req, res) => {
  try {
    const { url, imageableId, imageableType } = req.body;

    if (!['user', 'product'].includes(imageableType)) {
      return res.status(400).json({ error: 'imageableType must be "user" or "product"' });
    }

    const image = await Image.create({ url, imageableId, imageableType });
    res.status(201).json(image.toJSON());
  } catch (err) {
    res.status(400).json({ error: err.message });
  }
});

// GET /users/:id
app.get('/users/:id', async (req, res) => {
  try {
    const user = await User.findByPk(req.params.id, {
      include: [{ model: Image, as: 'profilePictures' }],
    });
    if (!user) {
      return res.status(404).json({ error: 'User not found' });
    }
    res.status(200).json(user.toJSON());
  } catch (err) {
    res.status(400).json({ error: err.message });
  }
});

// GET /products/:id
app.get('/products/:id', async (req, res) => {
  try {
    const product = await Product.findByPk(req.params.id, {
      include: [{ model: Image, as: 'productPhotos' }],
    });
    if (!product) {
      return res.status(404).json({ error: 'Product not found' });
    }
    res.status(200).json(product.toJSON());
  } catch (err) {
    res.status(400).json({ error: err.message });
  }
});

// GET /images/:id
app.get('/images/:id', async (req, res) => {
  try {
    const image = await Image.findByPk(req.params.id);
    if (!image) {
      return res.status(404).json({ error: 'Image not found' });
    }

    let imageable = null;
    if (image.imageableType === 'user') {
      imageable = await User.findByPk(image.imageableId);
    } else if (image.imageableType === 'product') {
      imageable = await Product.findByPk(image.imageableId);
    }

    const response = image.toJSON();
    response.imageable = imageable ? imageable.toJSON() : null;
    res.status(200).json(response);
  } catch (err) {
    res.status(400).json({ error: err.message });
  }
});

// Start the server after syncing the database
(async () => {
  try {
    await sequelize.sync();
    app.listen(PORT, () => {
      console.log(`Server is running on http://localhost:${PORT}`);
    });
  } catch (err) {
    console.error('Failed to start server:', err);
  }
})();

